<?php
/* NEMRA v143 installer - one file, run once, deletes itself.

   Writes 3 files to their correct paths, wherever this file is dropped inside public_html:
     index.html          the new landing page (Arabic + English)
     app/js/home6.js     the new app home screen
     app/index.html      the same file as now plus one line loading home6.js - written LAST
   Each file is checked against a SHA-256 before and after writing, and whatever it
   replaces is copied to _nemra-backup-<date>/ first. It writes nothing else.

   Upload anywhere inside public_html, open https://nemra.app/nemra-v143.php, read the report.
*/

header('Content-Type: text/html; charset=utf-8');
error_reporting(E_ALL);
ini_set('display_errors', '1');

function h($s) { return htmlspecialchars((string)$s, ENT_QUOTES, 'UTF-8'); }

$rows = [];
$fatal = null;

/* ---------- 1. find the site root, from wherever this file was dropped ---------- */
$root = null;
$dir  = __DIR__;
for ($i = 0; $i < 8; $i++) {
    if (is_file($dir . '/app/js/app.js') && is_file($dir . '/api/index.php')) { $root = $dir; break; }
    $up = dirname($dir);
    if ($up === $dir) break;
    $dir = $up;
}
if ($root === null) {
    $fatal = 'Could not find the site root. This file needs to sit somewhere inside '
           . 'public_html — the folder that holds app/ and api/. It changed nothing.';
}

$written = 0; $failed = 0; $skipped = 0;
$backupDir = null;

if ($fatal === null) {
    $PAYLOAD = json_decode('[{"p":"index.html","s":"2b25ac1e85e13c706f8676609905cab86d0c65c7dd4e5d6763441bcf3e17c10c","n":58297,"d":""},{"p":"app/js/home6.js","s":"2b672cc13dc734ca85ecb9fbff19b0a2fcebc1f8b262dddcc6a91fac6640eb45","n":18931,"d":""},{"p":"app/index.html","s":"c7da93f88820d296b287a8bc9396f916af6fd7aa59398b6ac392096fd238fa03","n":5006,"d":""}]', true);
    if (!is_array($PAYLOAD) || !count($PAYLOAD)) {
        $fatal = 'The embedded file list is unreadable. Nothing was changed.';
    } else {
        $backupDir = $root . '/_nemra-backup-' . date('Ymd-His');

        foreach ($PAYLOAD as $f) {
            $rel  = $f['p'];
            $dest = $root . '/' . $rel;
            $data = base64_decode($f['d'], true);

            if ($data === false || strlen($data) !== (int)$f['n']
                || hash('sha256', $data) !== $f['s']) {
                $rows[] = [$rel, 'FAILED', 'the copy inside this installer is damaged — not written'];
                $failed++;
                continue;
            }

            /* already exactly right? leave it alone and say so */
            if (is_file($dest) && hash_file('sha256', $dest) === $f['s']) {
                $rows[] = [$rel, 'already current', number_format(strlen($data)) . ' bytes'];
                $skipped++;
                continue;
            }

            $destDir = dirname($dest);
            if (!is_dir($destDir) && !@mkdir($destDir, 0755, true)) {
                $rows[] = [$rel, 'FAILED', 'could not create ' . basename($destDir) . '/'];
                $failed++;
                continue;
            }

            /* keep whatever is being replaced */
            $note = 'new file';
            if (is_file($dest)) {
                $bPath = $backupDir . '/' . $rel;
                if (!is_dir(dirname($bPath))) @mkdir(dirname($bPath), 0755, true);
                $note = @copy($dest, $bPath) ? 'replaced — old copy saved' : 'replaced — BACKUP FAILED';
            }

            if (@file_put_contents($dest, $data) === false) {
                $rows[] = [$rel, 'FAILED', 'could not write — check folder permissions'];
                $failed++;
                continue;
            }
            @chmod($dest, 0644);

            /* read it back; a write that reports success and lands wrong is the worst case */
            if (hash_file('sha256', $dest) !== $f['s']) {
                $rows[] = [$rel, 'FAILED', 'written but does not match — left in place, check it'];
                $failed++;
                continue;
            }
            $rows[] = [$rel, 'written', $note . ' · ' . number_format(strlen($data)) . ' bytes'];
            $written++;
        }
    }
}

/* ---------- 4. clear the strays from the failed extraction ---------- */
$cleaned = [];
if ($fatal === null && $failed === 0) {
    $strayFiles = [];
    foreach (['app/app', 'app/api'] as $strayRoot) {
        $base = $root . '/' . $strayRoot;
        if (!is_dir($base)) continue;
        $it = new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($base, FilesystemIterator::SKIP_DOTS),
            RecursiveIteratorIterator::CHILD_FIRST);
        foreach ($it as $item) {
            if ($item->isFile()) { if (@unlink($item->getPathname())) $strayFiles[] = $item->getPathname(); }
            elseif ($item->isDir()) { @rmdir($item->getPathname()); }
        }
        @rmdir($base);
        $cleaned[] = $strayRoot . (is_dir($base) ? ' — some of it is still there' : ' — removed');
    }
}

/* ---------- 5. remove this installer ---------- */
$selfGone = false;
if ($fatal === null) { $selfGone = @unlink(__FILE__); }

/* When this arrived by a Git pull into its own throwaway folder, remove that folder too
   (the .git copy included). Only ever a folder with this exact name, and never the site root. */
if ($fatal === null && basename(__DIR__) === '_nemra_deploy_v143' && realpath(__DIR__) !== realpath($root)) {
    $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator(__DIR__, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::CHILD_FIRST);
    foreach ($it as $item) { if ($item->isDir() && !$item->isLink()) @rmdir($item->getPathname()); else { @chmod($item->getPathname(), 0644); @unlink($item->getPathname()); } }
    @rmdir(__DIR__);
}
?>
<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Nemra v143 installer</title>
<style>
 :root{color-scheme:dark}
 body{margin:0;background:#0B1725;color:#EDF1F6;font:14px/1.6 system-ui,sans-serif;padding:26px}
 .wrap{max-width:860px;margin:0 auto}
 h1{font-size:19px;margin:0 0 4px}
 .sub{color:#93A2B6;font-size:13px;margin-bottom:20px}
 .big{border-radius:14px;padding:14px 16px;margin-bottom:18px;font-weight:700}
 .ok{background:rgba(63,163,127,.15);border:1px solid rgba(63,163,127,.5);color:#8FE0C4}
 .bad{background:rgba(224,64,58,.15);border:1px solid rgba(224,64,58,.5);color:#FFB3AF}
 table{width:100%;border-collapse:collapse;font-size:13px}
 th,td{text-align:start;padding:7px 10px;border-bottom:1px solid #22374F;vertical-align:top}
 th{color:#64758C;font-size:11px;text-transform:uppercase;letter-spacing:.06em}
 td.p{font-family:ui-monospace,Menlo,monospace;font-size:12.5px}
 .s-written{color:#F7C325;font-weight:700}
 .s-already{color:#64758C}
 .s-FAILED{color:#FF6B64;font-weight:700}
 ul{margin:10px 0 0;padding-inline-start:20px;color:#93A2B6;font-size:13px}
 .foot{margin-top:22px;padding-top:16px;border-top:1px solid #22374F;color:#93A2B6;font-size:13px}
 code{background:#14263D;padding:1px 6px;border-radius:5px;font-size:12.5px}
</style></head><body><div class="wrap">
<h1>Nemra v143 installer</h1>
<div class="sub"><?= date('Y-m-d H:i') ?></div>

<?php if ($fatal !== null): ?>
  <div class="big bad"><?= h($fatal) ?></div>
<?php else: ?>
  <?php if ($failed === 0): ?>
    <div class="big ok">Done — <?= $written ?> file<?= $written === 1 ? '' : 's' ?> written<?php
      if ($skipped) echo ', ' . $skipped . ' already current'; ?>. Nothing failed.</div>
  <?php else: ?>
    <div class="big bad"><?= $failed ?> file<?= $failed === 1 ? '' : 's' ?> could not be written.
      The rest went in. app/index.html is written last, so if it is in the failed list below your
      app is untouched and still working. Send me this page and I will tell you what to do.</div>
  <?php endif; ?>

  <table><thead><tr><th>file</th><th>result</th><th>detail</th></tr></thead><tbody>
  <?php foreach ($rows as $r): ?>
    <tr><td class="p"><?= h($r[0]) ?></td>
        <td class="s-<?= h(explode(' ', $r[1])[0]) ?>"><?= h($r[1]) ?></td>
        <td><?= h($r[2]) ?></td></tr>
  <?php endforeach; ?>
  </tbody></table>

  <div class="foot">
    <?php if ($backupDir && is_dir($backupDir)): ?>
      Everything replaced was copied to <code><?= h(basename($backupDir)) ?></code> in your site root
      first. Delete that folder once the app looks right.<br>
    <?php endif; ?>
    <?php if ($cleaned): ?>
      Cleared the leftovers from the failed upload:
      <ul><?php foreach ($cleaned as $c) echo '<li>' . h($c) . '</li>'; ?></ul>
    <?php endif; ?>
    <p><?= $selfGone
      ? 'This installer has deleted itself. Refresh this page — you should get a 404.'
      : '<b style="color:#FF6B64">This installer could NOT delete itself. Remove it by hand now:</b> <code>' . h(basename(__FILE__)) . '</code>' ?></p>
    <p>Next: clear the site cache in hPanel, then hard-refresh the app.</p>
  </div>
<?php endif; ?>
</div></body></html>
